-- RN Master native-format/case-study pilot import. Preserves matrix, cloze, highlight, bow-tie, SATA and MC formats.
begin;
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set31-Case','RN Master Set 31 unfolding case study','A 44-year-old client is admitted with tingling in the feet that began 5 days ago and has progressed to weakness in both legs and now the hips. Two weeks ago, the client had a diarrheal illness after eating undercooked chicken. Nurses'' notes, 0900: Symmetric weakness of both legs (2/5) and mild weakness of both arms (4/5). Deep tendon reflexes absent in the legs and diminished in the arms. Reports aching back and leg pain. Mild difficulty swallowing thin liquids. Alert and oriented. Vital signs over the past 4 hours: HR ranging from 48 to 128/min; BP ranging from 88/50 to 182/104 mm Hg; RR 22/min; SpO2 95% on room air. Respiratory measurements: forced vital capacity 22 mL/kg (baseline 50 mL/kg), negative inspiratory force −26 cm H2O. Lumbar puncture: elevated CSF protein with a normal white blood cell count.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set32-Case','RN Master Set 32 unfolding case study','A 26-year-old client, gravida 1 para 0, at 35 weeks'' gestation comes to labor and delivery reporting a severe headache that is not relieved by acetaminophen and "seeing spots." Nurses'' notes, 1400: Reports pain under the right ribs. Face and hands swollen. Patellar reflexes 4+ with 3 beats of ankle clonus. Fetal heart rate baseline 140/min with moderate variability; no contractions. Vital signs: BP 172/114 mm Hg (repeated 15 minutes later: 168/112), HR 96/min, RR 18/min, SpO2 98% on room air. Laboratory results: urine protein-to-creatinine ratio 0.9 (elevated), platelets 108,000/mm³, AST 88 units/L, ALT 94 units/L, creatinine 1.0 mg/dL.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set33-Case','RN Master Set 33 unfolding case study','A 58-year-old client experiencing homelessness is brought to the emergency department after being found outdoors in freezing weather, wearing wet clothing. Bystanders report the client had been drinking alcohol. Nurses'' notes, 0600: Lethargic and confused; responds to loud voice. Not shivering. Skin cold and pale. Fingers of both hands are white, waxy, hard, and numb. Pupils sluggish. Vital signs: core (esophageal) temperature 86°F (30°C), HR 42/min and irregular, BP 84/50 mm Hg, RR 8/min; pulse oximetry unable to obtain a reliable reading. ECG: slow atrial fibrillation with prominent J (Osborn) waves. Laboratory results: glucose 62 mg/dL, potassium 4.4 mEq/L, blood alcohol elevated.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set34-Case','RN Master Set 34 unfolding case study','A 76-year-old client with atrial fibrillation who is not on anticoagulation (stopped because of falls) arrives at the emergency department with sudden, severe abdominal pain around the umbilicus that began 4 hours ago. The client has vomited twice and had an urgent, forceful bowel movement. Nurses'' notes, 1500: Pain rated 10/10; client is writhing. Abdomen soft, mildly distended, with only mild tenderness and no guarding or rebound. Bowel sounds hyperactive. Vital signs: HR 124/min and irregularly irregular, BP 102/64 mm Hg, RR 24/min, T 99.6°F (37.6°C), SpO2 96% on room air. Laboratory results: lactate 4.8 mmol/L (0.5–2.0), WBC 18,200/mm³, arterial pH 7.29, HCO3 17 mEq/L. CT angiography shows an embolus occluding the superior mesenteric artery.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set35-Case','RN Master Set 35 unfolding case study','A 28-year-old client at 30 weeks'' gestation is brought to labor and delivery after a car crash. She was wearing only the lap belt, positioned across the top of her abdomen. A previous ultrasound showed a fundal (upper uterine) placenta. Nurses'' notes, 1600: Reports severe, constant abdominal pain. Moderate dark red vaginal bleeding. Uterus rigid, tender, and does not relax between frequent small contractions. Fetal heart rate baseline 170/min with minimal variability and recurrent late decelerations. Vital signs: HR 120/min, BP 96/58 mm Hg (prenatal baseline 118/74), RR 24/min, SpO2 97% on room air. Laboratory results: hemoglobin 9.2 g/dL, platelets 110,000/mm³, fibrinogen 150 mg/dL (normal in pregnancy about 300–600), blood type O negative.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set36-Case','RN Master Set 36 unfolding case study','A 19-year-old client with Burkitt lymphoma began induction chemotherapy 30 hours ago. The client received IV fluids and allopurinol before chemotherapy. Nurses'' notes, 0800: Reports nausea, fatigue, muscle cramps, tingling around the mouth, and a "fluttering" feeling in the chest. Urine output 20 mL/hr for the past 3 hours. Positive Chvostek''s sign. Vital signs: HR 110/min with frequent PVCs, BP 150/90 mm Hg, RR 20/min, SpO2 97% on room air, T 98.8°F (37.1°C). 12-lead ECG: peaked T waves. Laboratory results: potassium 6.6 mEq/L, phosphorus 8.9 mg/dL (2.5–4.5), calcium 6.8 mg/dL (8.6–10.2), uric acid 14.2 mg/dL (3.5–7.2), creatinine 2.3 mg/dL (baseline 0.8), BUN 45 mg/dL. G6PD status: not yet documented.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set37-Case','RN Master Set 37 unfolding case study','A 3-year-old is admitted with a fever of 103–104°F (39.4–40°C) for 6 days that has not responded to acetaminophen or ibuprofen. Nurses'' notes, 1000: Very irritable and difficult to console. Both eyes red without drainage. Lips red, dry, and cracked, with a bright red "strawberry" tongue. Blotchy red rash on the trunk. Hands and feet swollen and red. A single enlarged, tender lymph node (2 cm) on the right side of the neck. Lungs clear. Capillary refill 2 seconds. Vital signs: T 103.8°F (39.9°C), HR 156/min, RR 30/min, BP 96/60 mm Hg. Weight 14 kg. Laboratory results: C-reactive protein and ESR markedly elevated, platelets 520,000/mm³, albumin 2.8 g/dL, ALT mildly elevated, urinalysis with sterile pyuria. Echocardiogram is scheduled.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set38-Case','RN Master Set 38 unfolding case study','A 34-year-old client with epilepsy ran out of levetiracetam 4 days ago. The client is brought to the emergency department by EMS after a generalized tonic-clonic seizure that began at home. Nurses'' notes, 2210: The client has had continuous generalized tonic-clonic activity for 7 minutes (including prehospital time) without regaining consciousness between convulsions. Gurgling respirations with frothy, blood-tinged oral secretions from a bitten tongue. Urinary incontinence. No IV access yet. Vital signs: HR 136/min, BP 172/100 mm Hg, RR 28/min and irregular, SpO2 86% on room air, T 101.0°F (38.3°C). Point-of-care results: glucose 58 mg/dL, sodium 136 mEq/L.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set39-Case','RN Master Set 39 unfolding case study','A 17-year-old with sickle cell disease (HbSS) was admitted 2 days ago with a vaso-occlusive crisis causing back and leg pain. The client has a morphine PCA and IV fluids. The incentive spirometer at the bedside has not been used. Nurses'' notes, 0400: New right-sided chest pain that worsens with breathing, and a cough. Breathing is shallow, and the client is guarding the chest. Crackles in the right lower lobe. Drowsy but arousable. Vital signs: T 102.2°F (39°C), HR 124/min, RR 30/min, BP 112/66 mm Hg, SpO2 89% on room air. Laboratory and imaging results: hemoglobin 6.4 g/dL (baseline 8.5), WBC 19,000/mm³, reticulocytes elevated. Chest x-ray shows a new right lower lobe infiltrate.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set40-Case','RN Master Set 40 unfolding case study','A 52-year-old client who takes sertraline 150 mg daily and trazodone at bedtime was admitted with MRSA pneumonia. IV linezolid was started 24 hours ago. The client has also received tramadol for pleuritic pain and IV ondansetron for nausea. Nurses'' notes, 1400: Agitated, restless, and intermittently confused. Profuse sweating. Tremor of both hands. Hyperactive reflexes in the legs with sustained ankle clonus. Pupils dilated. Three episodes of diarrhea since noon. Muscle tone increased in the legs more than the arms. Vital signs: T 103.1°F (39.5°C), HR 132/min, BP 168/98 mm Hg, RR 24/min, SpO2 95% on 2 L/min. Laboratory results: CK 1,900 units/L (mildly elevated), creatinine 1.1 mg/dL, WBC 13,800/mm³.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set31-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Wide heart rate and BP swings show autonomic dysfunction, which can cause dangerous dysrhythmias. A normal SpO2 can be falsely reassuring in neuromuscular respiratory weakness.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Forced vital capacity 22 mL/kg (baseline 50)","correct":false},{"id":"s2","text":"Negative inspiratory force −26 cm H2O","correct":false},{"id":"s3","text":"Difficulty swallowing thin liquids","correct":false},{"id":"s4","text":"HR ranging from 48 to 128/min","correct":false},{"id":"s5","text":"BP ranging from 88/50 to 182/104 mm Hg","correct":false},{"id":"s6","text":"Weakness progressing to the hips","correct":true},{"id":"s7","text":"Alert and oriented","correct":false},{"id":"s8","text":"SpO2 95% on room air","correct":false}]}','RNMaster-Set31-Case','1'),
('Set31-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more consistent with Guillain-Barré syndrome or acute stroke. Guillain-Barré','','','GBS: symmetric ascending weakness, areflexia, recent infection, elevated CSF protein with normal cells. Stroke: sudden one-sided weakness, facial droop with aphasia. GBS is an immune-mediated polyneuropathy, often following Campylobacter or viral infection. Albuminocytologic dissociation in the CSF supports it. Stroke causes sudden, focal, usually one-sided deficits.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Acute stroke"}],"rows":[{"id":"r1","label":"Symmetric weakness ascending from the legs","correct":"c1"},{"id":"r2","label":"Absent deep tendon reflexes","correct":"c1"},{"id":"r3","label":"Diarrheal illness 2 weeks earlier","correct":"c1"},{"id":"r4","label":"Sudden weakness of one side of the body","correct":"c1"},{"id":"r5","label":"Facial droop on one side with aphasia","correct":"c1"},{"id":"r6","label":"Elevated CSF protein with a normal cell count","correct":"c1"}]}','RNMaster-Set31-Case','2'),
('Set31-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___ and is at greatest risk for ___2___.','','','failure and life-threatening autonomic dysfunction Myasthenia causes fatigable weakness with intact reflexes, and MS rarely produces this acute ascending pattern. In GBS, respiratory muscle involvement and autonomic instability are the main causes of death.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["Guillain-Barré syndrome","myasthenia gravis","multiple sclerosis","spinal cord compression"],"correct":"Guillain-Barré syndrome"},{"id":"b2","options":["respiratory failure and life-threatening autonomic dysfunction","hyperthermia","hypoglycemia","seizures"],"correct":"respiratory failure and life-threatening autonomic dysfunction"}]}','RNMaster-Set31-Case','3'),
('Set31-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV immunoglobulin or plasma exchange ☐|Frequent FVC and NIF measurements with plans for elective intubation if values decline ☐|Continuous cardiac monitoring ☐|VTE prophylaxis ☐|Swallow evaluation, with alternative nutrition if needed ☐|High-dose oral corticosteroids as primary therapy ☐|Vigorous resistance exercise of the weak muscles','A,B,C,D,E','IVIG or plasma exchange shortens the course. Close respiratory monitoring allows controlled intubation before crisis. Autonomic instability requires cardiac monitoring, immobility requires VTE prevention, and dysphagia requires aspiration precautions. Corticosteroids are not effective in GBS, and overexertion is avoided during the acute phase.','Integrated','Management of Care','{}','RNMaster-Set31-Case','4'),
('Set31-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Two days later, the client is intubated. During endotracheal suctioning, the HR suddenly drops from 88 to 36/min and BP falls to 76/40 mm Hg. What should the nurse do first?','Continue suctioning to clear all secretions|Stop suctioning, oxygenate the client, and prepare atropine while notifying the provider|Increase the suction pressure|Reposition the client prone','B','Autonomic dysfunction in GBS can cause severe bradycardia with vagal stimulation such as suctioning. The nurse stops the stimulus and oxygenates. Atropine or temporary pacing may be required.','Integrated','Adult Health','{}','RNMaster-Set31-Case','5'),
('Set31-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Over the following weeks, the nurse evaluates the client. For each finding, indicate whether it shows expected progress or requires follow-up. Expected   Requires Finding','','','Expected: returning strength, improving VC, effective communication, pain controlled. Follow-up: possible DVT; possible aspiration pneumonia. Recovery in GBS often proceeds in the reverse order of onset. Immobility increases DVT risk, and dysphagia with tube feeding increases aspiration risk. Both need prompt evaluation. Answers: Set 32: Mixed Review 15','Integrated','Adult Health','{"columns":[{"id":"c1","label":"follow-up"}],"rows":[{"id":"r1","label":"Arm strength returning, followed by leg strength","correct":"c1"},{"id":"r2","label":"Vital capacity improving, allowing a weaning trial","correct":"c1"},{"id":"r3","label":"Communicates effectively using a letter board","correct":"c1"},{"id":"r4","label":"Neuropathic pain controlled with gabapentin","correct":"c1"},{"id":"r5","label":"New swelling, warmth, and pain in the left calf","correct":"c1"},{"id":"r6","label":"Fever and new coarse crackles after tube feedings","correct":"c1"}]}','RNMaster-Set31-Case','6'),
('Set32-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','These are severe features of preeclampsia, indicating high risk for eclampsia, stroke, and HELLP syndrome. The fetal heart rate tracing is currently reassuring.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"BP 172/114 mm Hg, confirmed on repeat","correct":false},{"id":"s2","text":"Severe headache unrelieved by acetaminophen","correct":true},{"id":"s3","text":"Seeing spots","correct":false},{"id":"s4","text":"Pain under the right ribs","correct":true},{"id":"s5","text":"Reflexes 4+ with ankle clonus","correct":true},{"id":"s6","text":"Platelets 108,000/mm³","correct":true},{"id":"s7","text":"AST and ALT elevated","correct":true},{"id":"s8","text":"FHR 140/min with moderate variability","correct":true}]}','RNMaster-Set32-Case','1'),
('Set32-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is a severe feature of preeclampsia or can be a normal finding in late pregnancy. Severe         Can be normal','','','Severe features: SBP 160 or higher, refractory headache, falling platelets, RUQ/epigastric pain. Can be normal: mild dependent edema, heartburn. Dependent edema and heartburn are common in pregnancy. Severe-range BP, neurological symptoms, thrombocytopenia, liver involvement, pulmonary edema, and kidney dysfunction define severe features.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"feature of"},{"id":"c2","label":"in late"}],"rows":[{"id":"r1","label":"Systolic BP of 160 mm Hg or higher","correct":"c2"},{"id":"r2","label":"Mild ankle edema at the end of the day","correct":"c1"},{"id":"r3","label":"Headache not relieved by medication","correct":"c1"},{"id":"r4","label":"Platelets below 100,000–150,000 with falling trend","correct":"c1"},{"id":"r5","label":"Heartburn after meals","correct":"c1"},{"id":"r6","label":"Right upper quadrant or epigastric pain","correct":"c1"}]}','RNMaster-Set32-Case','2'),
('Set32-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___ and is at immediate risk for ___2___.','','','seizures and stroke Severe-range BP with proteinuria, neurological symptoms, and lab abnormalities confirms preeclampsia with severe features. Uncontrolled BP is a leading cause of maternal stroke.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["preeclampsia with severe features","gestational hypertension without severe features","migraine","gallbladder disease"],"correct":"preeclampsia with severe features"},{"id":"b2","options":["eclamptic seizures and stroke","preterm premature rupture of membranes","hypoglycemia","postpartum depression"],"correct":"eclamptic seizures and stroke"}]}','RNMaster-Set32-Case','3'),
('Set32-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV magnesium sulfate loading dose followed by a maintenance infusion ☐|IV labetalol or hydralazine (or oral immediate-release nifedipine) to lower severe-range BP within 30–60 minutes ☐|Seizure precautions and a quiet environment ☐|Strict intake and output with close monitoring of reflexes and respirations ☐|Continuous fetal monitoring and planning for delivery ☐|Encourage the client to ambulate in the hallway ☐|Give IV fluids rapidly at 250 mL/hr','A,B,C,D,E','Management includes seizure prophylaxis with magnesium, prompt antihypertensive treatment, monitoring for magnesium toxicity, fetal surveillance, and delivery planning (recommended at 34 weeks or later with severe features). Clients are at risk for pulmonary edema, so fluids are restricted.','Integrated','Pharmacology','{}','RNMaster-Set32-Case','4'),
('Set32-RN-24','Safety and Infection Control','Case study: Take action','single_best_answer','Before magnesium is started, the client has a generalized tonic-clonic seizure. What should the nurse do first?','Insert an oral airway between the client''s teeth|Turn the client onto her side, protect her from injury, call for help, and note the time|Restrain the client''s arms and legs|Begin chest compressions immediately','B','During an eclamptic seizure, side-lying positioning protects the airway and improves placental perfusion, and the client is protected from injury. After the seizure, oxygen is given, magnesium is started, and the fetus is assessed. Fetal bradycardia commonly recovers afterward.','Integrated','Safety & Infection Control','{}','RNMaster-Set32-Case','5'),
('Set32-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Six hours after treatment begins, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires follow-up. Requires','','','Effective: BP out of severe range, reflexes 2+, RR 16, adequate urine output. Follow-up: supratherapeutic magnesium level; recurrent late decelerations. Improved BP, normal reflexes, and adequate respirations and urine output show response. A magnesium level above the therapeutic range (about 4.8–8.4 mg/dL) risks toxicity. Recurrent late decelerations suggest uteroplacental insufficiency and may prompt expedited delivery. Answers: Set 33: Mixed Review 16','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"BP 148/94 mm Hg","correct":"c1"},{"id":"r2","label":"Patellar reflexes 2+ without clonus","correct":"c1"},{"id":"r3","label":"RR 16/min","correct":"c1"},{"id":"r4","label":"Urine output 40 mL/hr","correct":"c1"},{"id":"r5","label":"Serum magnesium 9.4 mg/dL","correct":"c1"},{"id":"r6","label":"Recurrent late decelerations on the fetal monitor","correct":"c1"}]}','RNMaster-Set32-Case','6'),
('Set33-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','A core temperature of 86°F indicates moderate to severe hypothermia with depressed cardiac, respiratory, and neurological function. Loss of shivering signals worsening hypothermia. Frostbite and hypoglycemia also need treatment. Potassium is normal.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Core temperature 86°F (30°C)","correct":true},{"id":"s2","text":"HR 42/min and irregular","correct":true},{"id":"s3","text":"RR 8/min","correct":false},{"id":"s4","text":"BP 84/50 mm Hg","correct":false},{"id":"s5","text":"Not shivering","correct":true},{"id":"s6","text":"White, waxy, hard fingers","correct":true},{"id":"s7","text":"Glucose 62 mg/dL","correct":false},{"id":"s8","text":"Potassium 4.4 mEq/L","correct":false}]}','RNMaster-Set33-Case','1'),
('Set33-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects systemic hypothermia or local cold injury (frostbite). Systemic','','','Systemic: bradycardia, no shivering, J waves. Frostbite: white waxy hard skin, numbness, blisters after rewarming. Hypothermia slows metabolism and cardiac conduction. Frostbite is freezing of local tissue. Blister type after rewarming helps estimate depth: clear blisters suggest superficial injury, and hemorrhagic blisters suggest deeper injury.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Frostbite"}],"rows":[{"id":"r1","label":"Bradycardia","correct":"c1"},{"id":"r2","label":"Absence of shivering","correct":"c1"},{"id":"r3","label":"J (Osborn) waves on the ECG","correct":"c1"},{"id":"r4","label":"White, waxy, hard fingers","correct":"c1"},{"id":"r5","label":"Numbness of the fingers","correct":"c1"},{"id":"r6","label":"Blisters on the fingers after rewarming","correct":"c1"}]}','RNMaster-Set33-Case','2'),
('Set33-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___ and is at high risk for ___2___.','','','Rough handling or rapid position changes can trigger VF. Alcohol worsens heat loss by causing vasodilation.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["moderate to severe accidental hypothermia with frostbite","mild hypothermia only","sepsis with fever","an opioid overdose only"],"correct":"moderate to severe accidental hypothermia with frostbite"},{"id":"b2","options":["ventricular fibrillation","hypertensive crisis","hyperthermia","diabetes insipidus"],"correct":"ventricular fibrillation"}]}','RNMaster-Set33-Case','3'),
('Set33-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Handle the client gently and keep them horizontal ☐|Remove wet clothing and begin active external rewarming (such as forced-air warming blankets) ☐|Warmed IV fluids and warmed, humidified oxygen ☐|Continuous cardiac monitoring ☐|IV dextrose for hypoglycemia ☐|Rub the frostbitten fingers vigorously to restore circulation ☐|Give hot coffee by mouth','A,B,C,D,E','Rewarming (external and core), gentle handling, cardiac monitoring, and correcting hypoglycemia are key. Frostbitten tissue is never rubbed, because rubbing damages it. Rapid rewarming of frostbite is done later in warm water. Oral intake is unsafe with decreased consciousness.','Integrated','Management of Care','{}','RNMaster-Set33-Case','4'),
('Set33-RN-24','Safety and Infection Control','Case study: Take action','single_best_answer','The client needs to be moved from the stretcher to the emergency department bed. What is most important for the nurse to do?','Have the client sit up and pivot to the bed|Move the client gently while keeping them horizontal, with minimal jostling|Walk the client to the bed to generate body heat|Move the client quickly to save time','B','The cold heart is very prone to ventricular fibrillation with rough movement. Keeping the client horizontal also helps prevent hypotension.','Integrated','Safety & Infection Control','{}','RNMaster-Set33-Case','5'),
('Set33-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Four hours after rewarming begins, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires follow-up. Requires','','','Effective: core temp 95°F, sinus rhythm, improved mentation, stable BP. Follow-up: deep frostbite (hemorrhagic blisters); severe hyperkalemia. Gradual rewarming with restored rhythm and mentation shows success. Hemorrhagic blisters indicate deep frostbite that may need specialized care, such as thrombolytics in select cases. Severe hyperkalemia can signal tissue damage and needs urgent treatment. Answers: Set 34: Mixed Review 17','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Core temperature 95°F (35°C)","correct":"c1"},{"id":"r2","label":"HR 76/min in sinus rhythm","correct":"c1"},{"id":"r3","label":"Responds appropriately to questions","correct":"c1"},{"id":"r4","label":"BP 116/70 mm Hg","correct":"c1"},{"id":"r5","label":"Fingers dusky with blood-filled blisters","correct":"c1"},{"id":"r6","label":"Potassium rising to 7.0 mEq/L","correct":"c1"}]}','RNMaster-Set33-Case','6'),
('Set34-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Severe pain with a relatively benign exam is the classic sign of early mesenteric ischemia. Elevated lactate and acidosis indicate tissue hypoperfusion. AF without anticoagulation is the embolic source. SpO2 is acceptable.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Pain 10/10 with only mild tenderness on exam","correct":true},{"id":"s2","text":"HR 124/min, irregularly irregular","correct":false},{"id":"s3","text":"BP 102/64 mm Hg","correct":false},{"id":"s4","text":"Lactate 4.8 mmol/L","correct":true},{"id":"s5","text":"pH 7.29 with HCO3 17 mEq/L","correct":true},{"id":"s6","text":"WBC 18,200/mm³","correct":false},{"id":"s7","text":"Not on anticoagulation","correct":true},{"id":"s8","text":"SpO2 96% on room air","correct":false}]}','RNMaster-Set34-Case','1'),
('Set34-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more typical of early mesenteric ischemia or progression to bowel infarction. Progression','','','Early: pain out of proportion, forceful bowel emptying, hyperactive bowel sounds. Infarction: peritoneal signs, bloody stools, fever with hypotension. Early ischemia causes intense pain and gut spasm before the full bowel wall is damaged. Peritoneal signs, bleeding, and sepsis indicate transmural necrosis, which greatly increases mortality.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Early ischemia"}],"rows":[{"id":"r1","label":"Severe pain with a soft abdomen","correct":"c1"},{"id":"r2","label":"Urgent, forceful bowel movement","correct":"c1"},{"id":"r3","label":"Hyperactive bowel sounds","correct":"c1"},{"id":"r4","label":"Abdominal rigidity with rebound tenderness","correct":"c1"},{"id":"r5","label":"Bloody stools","correct":"c1"},{"id":"r6","label":"Fever with hypotension","correct":"c1"}]}','RNMaster-Set34-Case','2'),
('Set34-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___ and is at high risk for ___2___.','','','Every hour of delay increases bowel death and mortality.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["acute mesenteric ischemia from an embolus related to atrial fibrillation","gastroenteritis","irritable bowel syndrome","constipation"],"correct":"acute mesenteric ischemia from an embolus related to atrial fibrillation"},{"id":"b2","options":["bowel necrosis, perforation, and sepsis","hypoglycemia","hypertensive crisis","urinary retention"],"correct":"bowel necrosis, perforation, and sepsis"}]}','RNMaster-Set34-Case','3'),
('Set34-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Keep the client NPO with nasogastric decompression ☐|IV isotonic fluid resuscitation ☐|IV heparin as prescribed ☐|Broad-spectrum IV antibiotics ☐|Preparation for emergency revascularization and possible bowel resection ☐|A cleansing enema ☐|Waiting 24 hours for the pain to localize before further action','A,B,C,D,E','Management includes resuscitation, anticoagulation to prevent clot extension, antibiotics for bacterial translocation, and urgent restoration of blood flow with removal of dead bowel. Enemas and delays are harmful.','Integrated','Management of Care','{}','RNMaster-Set34-Case','4'),
('Set34-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which prescription should the nurse implement first?','Establish large-bore IV access and begin isotonic fluid resuscitation|Insert a urinary catheter|Obtain a stool sample|Encourage sips of clear liquids','A','Restoring circulating volume supports bowel perfusion and treats hypoperfusion shown by the elevated lactate. The client remains NPO.','Integrated','Adult Health','{}','RNMaster-Set34-Case','5'),
('Set34-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','The client undergoes embolectomy and bowel resection and is on a heparin infusion. On postoperative day 1, the nurse reassesses. For each finding, indicate whether it shows expected recovery or requires immediate follow-up. Expected   Requires Finding','','','Expected: normalized lactate, controlled HR, adequate urine output, controlled pain. Follow-up: recurrent ischemia; excessive anticoagulation with bleeding. A falling lactate and stable vital signs show restored perfusion. A rising lactate with distention suggests ongoing ischemia, and a planned second-look surgery may be needed. Bleeding with a supratherapeutic aPTT requires adjusting the heparin. Answers: Set 35: Mixed Review 18','Integrated','Adult Health','{"columns":[{"id":"c1","label":"follow-up"}],"rows":[{"id":"r1","label":"Lactate 1.6 mmol/L","correct":"c1"},{"id":"r2","label":"HR 88/min","correct":"c1"},{"id":"r3","label":"Urine output 45 mL/hr","correct":"c1"},{"id":"r4","label":"Pain 4/10 with PCA","correct":"c1"},{"id":"r5","label":"Rising lactate with increasing abdominal distention","correct":"c1"}]}','RNMaster-Set34-Case','6'),
('Set35-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','fibrinogen; falling platelets; Rh-negative status These findings indicate placental abruption with fetal compromise, maternal hemorrhage, and developing coagulopathy. Rh-negative status requires Rh immune globulin after trauma. Pregnancy''s increased blood volume can hide significant blood loss until late.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Rigid, tender uterus that doesn''t relax","correct":true},{"id":"s2","text":"Dark red vaginal bleeding with constant pain","correct":true},{"id":"s3","text":"FHR 170/min with minimal variability and late decelerations","correct":true},{"id":"s4","text":"HR 120/min with BP 96/58 mm Hg","correct":true},{"id":"s5","text":"Fibrinogen 150 mg/dL","correct":false},{"id":"s6","text":"Platelets 110,000/mm³","correct":false},{"id":"s7","text":"Blood type O negative","correct":false},{"id":"s8","text":"SpO2 97% on room air","correct":false}]}','RNMaster-Set35-Case','1'),
('Set35-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more consistent with placental abruption or placenta previa. Placental   Placenta Finding','','','Abruption: painful rigid uterus, dark bleeding, trauma. Previa: painless bright red bleeding, soft uterus, low-lying placenta. In abruption, the placenta separates from the uterine wall, causing pain and blood that may be concealed behind the placenta. In previa, the placenta covers or is near the cervix and bleeds painlessly as the cervix changes.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"previa"}],"rows":[{"id":"r1","label":"Painful, rigid uterus","correct":"c1"},{"id":"r2","label":"Dark red bleeding","correct":"c1"},{"id":"r3","label":"Recent abdominal trauma","correct":"c1"},{"id":"r4","label":"Painless, bright red bleeding","correct":"c1"},{"id":"r5","label":"Soft, nontender uterus","correct":"c1"},{"id":"r6","label":"Placenta low in the uterus near or over the cervix","correct":"c1"}]}','RNMaster-Set35-Case','2'),
('Set35-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___ with ___2___.','','','compromise, maternal hemorrhage, and early DIC Abruption releases tissue factor that consumes clotting factors, causing a falling fibrinogen. A fibrinogen below 200 mg/dL is associated with severe hemorrhage. Fetal tachycardia, minimal variability, and late decelerations indicate hypoxia.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["placental abruption","placenta previa","preterm labor without complications","round ligament pain"],"correct":"placental abruption"},{"id":"b2","options":["fetal compromise, maternal hemorrhage, and early DIC","a reassuring fetal status","a urinary tract infection","normal pregnancy findings"],"correct":"fetal compromise, maternal hemorrhage, and early DIC"}]}','RNMaster-Set35-Case','3'),
('Set35-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Left lateral positioning or manual uterine displacement ☐|Two large-bore IVs with blood products, including cryoprecipitate or fibrinogen as prescribed ☐|Continuous fetal monitoring ☐|Preparation for emergency cesarean birth ☐|Rh immune globulin, with testing to determine the dose needed ☐|Tocolytics to stop the contractions ☐|Delaying delivery until 34 weeks for corticosteroids','A,B,C,D,E','Management includes positioning to improve placental perfusion, hemorrhage and coagulopathy resuscitation, fetal surveillance, and expedited delivery when mother or fetus is compromised. A Kleihauer-Betke test guides the Rh immune globulin dose after trauma. Tocolytics are contraindicated in abruption, and delay risks fetal death.','Integrated','Management of Care','{}','RNMaster-Set35-Case','4'),
('Set35-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Position the client on her left side (or tilt the uterus to the left)|Obtain a Kleihauer-Betke test|Administer Rh immune globulin|Perform a digital cervical exam','A','Lateral positioning relieves aortocaval compression, improving venous return, maternal cardiac output, and placental blood flow. The other actions follow.','Integrated','Adult Health','{}','RNMaster-Set35-Case','5'),
('Set35-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After emergency cesarean birth and transfusion, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires immediate follow-up. Requires','','','Effective: firm fundus, stable BP, improved fibrinogen, stable newborn. Follow-up: oozing (possible ongoing DIC); oliguria (possible hypoperfusion or AKI). A firm uterus, stabilized hemodynamics, and corrected fibrinogen show response. Oozing from multiple sites suggests continuing coagulopathy, and low urine output suggests inadequate perfusion or kidney injury. Answers: Set 36: Mixed Review 19','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Fundus firm at the umbilicus","correct":"c1"},{"id":"r2","label":"BP 118/72 mm Hg after 2 units of packed red cells","correct":"c1"},{"id":"r3","label":"Fibrinogen 260 mg/dL after cryoprecipitate","correct":"c1"},{"id":"r4","label":"Newborn stable in the NICU","correct":"c1"},{"id":"r5","label":"Oozing from IV sites and around the incision","correct":"c1"},{"id":"r6","label":"Urine output 15 mL/hr for 2 hours","correct":"c1"}]}','RNMaster-Set35-Case','6'),
('Set36-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','status These are the hallmark metabolic abnormalities of tumor lysis syndrome, which can cause lethal dysrhythmias, seizures, and kidney failure. G6PD status matters before rasburicase. SpO2 is normal.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Potassium 6.6 mEq/L with peaked T waves","correct":true},{"id":"s2","text":"Frequent PVCs","correct":true},{"id":"s3","text":"Calcium 6.8 mg/dL with positive Chvostek''s sign","correct":true},{"id":"s4","text":"Phosphorus 8.9 mg/dL","correct":false},{"id":"s5","text":"Uric acid 14.2 mg/dL","correct":true},{"id":"s6","text":"Creatinine 2.3 mg/dL with urine output 20 mL/hr","correct":true},{"id":"s7","text":"SpO2 97% on room air","correct":false},{"id":"s8","text":"G6PD status not documented","correct":true}]}','RNMaster-Set36-Case','1'),
('Set36-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects hyperkalemia, hypocalcemia, or acute kidney injury. Acute kidney','','','Hyperkalemia: peaked T waves, ectopy with K 6.6. Hypocalcemia: cramps and tingling, Chvostek''s sign. AKI: rising creatinine, oliguria. Lysed tumor cells release potassium, phosphate, and nucleic acids. Phosphate binds calcium, and uric acid and calcium-phosphate crystals damage the kidneys, which further impairs potassium excretion.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Hyperkalemia"},{"id":"c2","label":"Hypocalcemia"}],"rows":[{"id":"r1","label":"Peaked T waves","correct":"c2"},{"id":"r2","label":"Positive Chvostek''s sign","correct":"c1"},{"id":"r3","label":"Rising creatinine","correct":"c1"},{"id":"r4","label":"Urine output 20 mL/hr","correct":"c1"}]}','RNMaster-Set36-Case','2'),
('Set36-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___, and the most immediate threat to life is ___2___.','','','cardiac dysrhythmia from hyperkalemia Burkitt lymphoma is highly chemosensitive and carries a high risk of TLS. Hyperkalemia with ECG changes can progress to ventricular fibrillation.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["tumor lysis syndrome","hypercalcemia of malignancy","SIADH","neutropenic sepsis"],"correct":"tumor lysis syndrome"},{"id":"b2","options":["a cardiac dysrhythmia from hyperkalemia","hypoglycemia","hypertensive stroke","dehydration from diarrhea"],"correct":"a cardiac dysrhythmia from hyperkalemia"}]}','RNMaster-Set36-Case','3'),
('Set36-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Aggressive IV hydration with close monitoring of urine output ☐|Rasburicase, after G6PD status is confirmed ☐|Continuous cardiac monitoring ☐|Treatment of hyperkalemia as prescribed (calcium gluconate for ECG changes, insulin with dextrose) ☐|Nephrology consultation for possible dialysis ☐|Adding potassium chloride to the IV fluids ☐|Restricting all fluids','A,B,C,D,E','Hydration improves kidney excretion, rasburicase rapidly lowers uric acid, and hyperkalemia is treated urgently. Dialysis may be needed for refractory abnormalities or kidney failure. Potassium supplementation and fluid restriction would worsen the condition.','Integrated','Management of Care','{}','RNMaster-Set36-Case','4'),
('Set36-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','Rasburicase is prescribed. Which action is essential before the nurse administers it?','Confirm the client''s G6PD status|Give it with grapefruit juice|Confirm that the client has eaten|Check a hemoglobin A1C','A','Rasburicase generates hydrogen peroxide and can cause severe hemolysis and methemoglobinemia in people with G6PD deficiency. Testing is required before use.','Integrated','Pharmacology','{}','RNMaster-Set36-Case','5'),
('Set36-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twenty-four hours later, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires follow-up. Requires','','','Effective: normal potassium and ECG, good urine output, normal uric acid, improving creatinine. Follow-up: fluid overload; possible hemolysis. Normalized electrolytes and improving kidney function show response. Aggressive hydration can cause pulmonary edema, requiring diuretics or dialysis. Dark urine with falling hemoglobin suggests hemolysis, which occurs with unrecognized G6PD deficiency. Answers: Set 37: Mixed Review 20','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Potassium 4.8 mEq/L with normal T waves","correct":"c1"},{"id":"r2","label":"Urine output 100 mL/hr","correct":"c1"},{"id":"r3","label":"Uric acid 4.9 mg/dL","correct":"c1"},{"id":"r4","label":"Creatinine trending down to 1.6 mg/dL","correct":"c1"},{"id":"r5","label":"New crackles and SpO2 88% on room air","correct":"c1"},{"id":"r6","label":"Dark brown urine with a falling hemoglobin after rasburicase","correct":"c1"}]}','RNMaster-Set36-Case','6'),
('Set37-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that support the suspected diagnosis and require follow-up.','','','extremity changes, cervical lymphadenopathy) meets criteria for Kawasaki disease. Clear lungs and normal perfusion are reassuring.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Fever for 6 days unresponsive to antipyretics","correct":true},{"id":"s2","text":"Red eyes without drainage","correct":false},{"id":"s3","text":"Cracked lips and strawberry tongue","correct":false},{"id":"s4","text":"Swollen, red hands and feet","correct":false},{"id":"s5","text":"Single enlarged cervical lymph node","correct":true},{"id":"s6","text":"Rash on the trunk","correct":true},{"id":"s7","text":"Lungs clear","correct":false},{"id":"s8","text":"Capillary refill 2 seconds","correct":false}]}','RNMaster-Set37-Case','1'),
('Set37-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it typically occurs in the acute phase or the subacute phase of Kawasaki disease. Subacute','','','Acute: fever, conjunctivitis, extremity swelling. Subacute: desquamation, thrombocytosis, peak aneurysm risk. The acute phase lasts about 1–2 weeks. The subacute phase (about weeks 2–4) brings periungual peeling, rising platelets, and the greatest risk of coronary aneurysm and thrombosis.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Acute phase"}],"rows":[{"id":"r1","label":"High fever","correct":"c1"},{"id":"r2","label":"Conjunctival injection","correct":"c1"},{"id":"r3","label":"Swollen, red hands and feet","correct":"c1"},{"id":"r4","label":"Peeling skin on the fingers and toes","correct":"c1"},{"id":"r5","label":"Platelet count peaking, often above 700,000/mm³","correct":"c1"},{"id":"r6","label":"Highest risk of coronary artery aneurysm development","correct":"c1"}]}','RNMaster-Set37-Case','2'),
('Set37-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The child most likely has ___1___, and the most serious complication to prevent is ___2___.','','','artery aneurysms Kawasaki disease is an acute vasculitis and a leading cause of acquired heart disease in children. Scarlet fever and measles have different features, such as a sandpaper rash with strep or a cough with Koplik spots, and would not persist despite appropriate care.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["Kawasaki disease","scarlet fever","measles","juvenile idiopathic arthritis"],"correct":"Kawasaki disease"},{"id":"b2","options":["coronary artery aneurysms","hearing loss only","hypoglycemia","kidney stones"],"correct":"coronary artery aneurysms"}]}','RNMaster-Set37-Case','3'),
('Set37-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV immunoglobulin (IVIG) as a single high-dose infusion ☐|High- or moderate-dose aspirin initially, followed by low-dose aspirin ☐|Echocardiograms at diagnosis and follow-up ☐|Monitoring for IVIG infusion reactions and fluid overload ☐|Comfort measures such as lip care and a calm environment ☐|Live vaccines (such as MMR) next week as scheduled ☐|Ibuprofen along with aspirin','A,B,C,D,E','IVIG given within 10 days of fever onset greatly reduces aneurysm risk. Aspirin provides anti-inflammatory and antiplatelet effects. Live vaccines are delayed about 11 months after IVIG, and ibuprofen interferes with aspirin''s antiplatelet effect.','Integrated','Pharmacology','{}','RNMaster-Set37-Case','4'),
('Set37-RN-24','Safety and Infection Control','Case study: Take action','single_best_answer','While the child is taking aspirin, the parent reports that a sibling at home was just diagnosed with influenza. What should the nurse do?','Reassure the parent that no action is needed|Notify the provider, because influenza or varicella during aspirin therapy increases the risk of Reye''s syndrome|Double the aspirin dose|Give the child the live intranasal flu vaccine','B','Aspirin plus influenza or varicella infection is associated with Reye''s syndrome, which can cause liver failure and encephalopathy. The provider may adjust therapy, and inactivated influenza vaccination is recommended.','Integrated','Safety & Infection Control','{}','RNMaster-Set37-Case','5'),
('Set37-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After IVIG, the nurse evaluates the child. For each finding, indicate whether it shows expected response or requires follow-up. Expected          Requires Finding','','','Expected: fever resolves, improved behavior, fingertip peeling (expected subacute finding), falling CRP. Follow-up: persistent fever (IVIG resistance), coronary dilation. Fever lasting more than 36 hours after IVIG suggests resistance, which usually requires a second dose or other therapy. Coronary changes require cardiology management and closer follow-up. Answers: Set 38: Mixed Review 21','Integrated','Adult Health','{"columns":[{"id":"c1","label":"follow-up"}],"rows":[{"id":"r1","label":"Afebrile within 24 hours after IVIG","correct":"c1"},{"id":"r2","label":"Less irritable and eating better","correct":"c1"},{"id":"r3","label":"Peeling of fingertips at 2 weeks","correct":"c1"},{"id":"r4","label":"CRP decreasing","correct":"c1"},{"id":"r5","label":"Fever persisting 40 hours after the IVIG infusion ended","correct":"c1"},{"id":"r6","label":"Echocardiogram shows coronary artery dilation","correct":"c1"}]}','RNMaster-Set37-Case','6'),
('Set38-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','hypoglycemia need immediate correction, and without IV access, an IM or intranasal benzodiazepine is needed. Incontinence is expected during seizures, and sodium is normal.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Continuous seizure activity for 7 minutes","correct":true},{"id":"s2","text":"Gurgling respirations with frothy secretions","correct":true},{"id":"s3","text":"SpO2 86% on room air","correct":false},{"id":"s4","text":"Glucose 58 mg/dL","correct":false},{"id":"s5","text":"Ran out of levetiracetam 4 days ago","correct":false},{"id":"s6","text":"No IV access","correct":true},{"id":"s7","text":"Urinary incontinence","correct":false},{"id":"s8","text":"Sodium 136 mEq/L","correct":false}]}','RNMaster-Set38-Case','1'),
('Set38-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more likely a consequence of the prolonged seizure or a possible cause or trigger to identify and treat. Consequence   Possible Finding','','','Consequences: tachycardia/hypertension, hyperthermia, tongue laceration. Causes: missed doses, hypoglycemia, subtherapeutic drug level. Prolonged convulsions cause sympathetic surge, heat production, and injury. Common triggers include antiepileptic nonadherence, hypoglycemia, electrolyte disturbances, alcohol withdrawal, and infection, and these must be identified and corrected.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"cause/trigger"}],"rows":[{"id":"r1","label":"Missed levetiracetam doses","correct":"c1"},{"id":"r2","label":"Glucose 58 mg/dL","correct":"c1"},{"id":"r3","label":"Tachycardia and hypertension","correct":"c1"},{"id":"r4","label":"Temperature 101.0°F","correct":"c1"},{"id":"r5","label":"Tongue laceration","correct":"c1"},{"id":"r6","label":"Subtherapeutic antiepileptic level","correct":"c1"}]}','RNMaster-Set38-Case','2'),
('Set38-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___ and is at risk for ___2___.','','','Seizures become harder to stop the longer they continue.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["convulsive status epilepticus","a simple febrile seizure","a psychogenic nonepileptic event","syncope"],"correct":"convulsive status epilepticus"},{"id":"b2","options":["hypoxic brain injury, aspiration, and rhabdomyolysis","hypothermia","urinary retention","hypertensive pregnancy complications"],"correct":"hypoxic brain injury, aspiration, and rhabdomyolysis"}]}','RNMaster-Set38-Case','3'),
('Set38-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IM midazolam now (or IV lorazepam once access is obtained) ☐|Dextrose for hypoglycemia, with thiamine if alcohol use or malnutrition is suspected ☐|A second-line IV antiepileptic, such as levetiracetam, fosphenytoin, or valproate, if seizures continue ☐|Side-lying positioning, suctioning, and high-flow oxygen ☐|Labs including electrolytes, CK, and antiepileptic drug level ☐|Restraining the client''s limbs ☐|Giving the missed oral levetiracetam by mouth during the seizure','A,B,C,D,E','Status epilepticus treatment is time-sensitive: a benzodiazepine first, then a second-line agent, while supporting the airway and correcting glucose. Restraints cause injury, and nothing is given by mouth during a seizure.','Integrated','Pharmacology','{}','RNMaster-Set38-Case','4'),
('Set38-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','As the client arrives, which action should the nurse take first?','Draw a levetiracetam level|Turn the client onto the side, suction the airway, and apply high-flow oxygen|Force an oral airway between the clenched teeth|Obtain a detailed seizure history from EMS','B','Protecting the airway and correcting hypoxemia are the first priorities, done at the same time as preparing medications. Forcing objects between clenched teeth causes injury, and a nasal airway may be used if needed.','Integrated','Adult Health','{}','RNMaster-Set38-Case','5'),
('Set38-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After IM midazolam, dextrose, and IV levetiracetam, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires immediate follow-up. Requires','','','Effective: seizures stopped, oxygenation restored, glucose corrected, expected postictal recovery. Follow-up: rhabdomyolysis; recurrent status epilepticus. Ending the seizure, restoring oxygenation and glucose, and gradual recovery of consciousness show response. Very high CK with dark urine indicates rhabdomyolysis, which requires aggressive IV fluids. Recurrent seizures without recovery indicate refractory status epilepticus, which may need intubation and continuous infusion therapy. Answers: Set 39: Mixed Review 22','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Convulsions stopped","correct":"c1"},{"id":"r2","label":"SpO2 97% on nonrebreather mask","correct":"c1"},{"id":"r3","label":"Glucose 112 mg/dL","correct":"c1"},{"id":"r4","label":"Groggy but responds to voice 30 minutes later","correct":"c1"},{"id":"r5","label":"CK 24,000 units/L with dark, tea-colored urine","correct":"c1"}]}','RNMaster-Set38-Case','6'),
('Set39-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','defines acute chest syndrome, a leading cause of death in sickle cell disease. Not using incentive spirometry is a modifiable risk factor. BP is stable.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"New chest pain with shallow breathing","correct":true},{"id":"s2","text":"SpO2 89% on room air","correct":false},{"id":"s3","text":"T 102.2°F (39°C)","correct":false},{"id":"s4","text":"RR 30/min","correct":false},{"id":"s5","text":"New right lower lobe infiltrate","correct":true},{"id":"s6","text":"Hemoglobin 6.4 g/dL (baseline 8.5)","correct":true},{"id":"s7","text":"Incentive spirometer unused","correct":true},{"id":"s8","text":"BP 112/66 mm Hg","correct":false}]}','RNMaster-Set39-Case','1'),
('Set39-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each item, indicate whether it is a contributing factor to acute chest syndrome or a clinical finding of it. Contributing   Clinical Finding','','','Contributing: shallow breathing from pain, opioid sedation, unused incentive spirometer. Findings: new infiltrate, hypoxemia, fever. Hypoventilation during a pain crisis causes atelectasis and hypoxia, which promote sickling in the lungs. Infection and fat embolism from bone marrow infarction are other causes.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"finding"}],"rows":[{"id":"r1","label":"Shallow breathing from back and chest pain","correct":"c1"},{"id":"r2","label":"Sedation from opioids reducing deep breaths","correct":"c1"},{"id":"r3","label":"Not using the incentive spirometer","correct":"c1"},{"id":"r4","label":"New lobar infiltrate on chest x-ray","correct":"c1"},{"id":"r5","label":"SpO2 89% on room air","correct":"c1"},{"id":"r6","label":"Fever of 102.2°F","correct":"c1"}]}','RNMaster-Set39-Case','2'),
('Set39-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___ and is at high risk for ___2___.','','','The hemoglobin drop suggests hemolysis or pooling of blood in the lungs.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["acute chest syndrome","splenic sequestration","a simple vaso-occlusive crisis","iron deficiency anemia"],"correct":"acute chest syndrome"},{"id":"b2","options":["progressive respiratory failure","hypertensive crisis","hypoglycemia","kidney stones"],"correct":"progressive respiratory failure"}]}','RNMaster-Set39-Case','3'),
('Set39-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Supplemental oxygen to reach the prescribed saturation target ☐|Incentive spirometry every 1–2 hours while awake ☐|Broad-spectrum antibiotics (such as ceftriaxone plus a macrolide) ☐|Blood transfusion (simple or exchange) as prescribed ☐|Effective pain control with monitoring of sedation and respiratory rate ☐|Increasing IV fluids to three times maintenance ☐|Stopping all opioid pain medication','A,B,C,D,E','Management includes oxygenation, lung expansion, treating possible infection including atypical organisms, transfusion to improve oxygen delivery, and balanced analgesia. Excess fluids can cause pulmonary edema, and untreated pain worsens splinting.','Integrated','Management of Care','{}','RNMaster-Set39-Case','4'),
('Set39-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Apply oxygen and raise the head of the bed|Increase the morphine PCA basal rate|Obtain a sputum culture|Encourage the client to walk in the hallway','A','Hypoxemia is the most immediate threat, and hypoxia promotes further sickling. The nurse then notifies the provider and coaches incentive spirometry. Increasing opioids could worsen hypoventilation.','Integrated','Adult Health','{}','RNMaster-Set39-Case','5'),
('Set39-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Forty-eight hours after treatment begins, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: oxygenation, afebrile, good incentive spirometer volumes, controlled pain. Follow-up: possible stroke; opioid oversedation. Improving oxygenation, infection control, lung expansion, and pain show response. Sickle cell disease raises stroke risk, so new neurological signs require emergency evaluation. Oversedation with slow breathing requires stopping opioids, airway support, and possibly naloxone. Answers: Set 40: Mixed Review 23 (Final Set)','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"SpO2 96% on 2 L/min nasal cannula","correct":"c1"},{"id":"r2","label":"Afebrile for 24 hours","correct":"c1"},{"id":"r3","label":"Achieving 1,500 mL on the incentive spirometer","correct":"c1"},{"id":"r4","label":"Pain 4/10 with oral analgesics","correct":"c1"},{"id":"r5","label":"Sudden severe headache and slurred speech","correct":"c1"}]}','RNMaster-Set39-Case','6'),
('Set40-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','These findings match serotonin toxicity. Linezolid is an MAO inhibitor, and combining it with an SSRI, tramadol, trazodone, and ondansetron greatly increases serotonin activity. The WBC reflects the pneumonia, and SpO2 is acceptable.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Agitation and confusion","correct":true},{"id":"s2","text":"Sustained ankle clonus with hyperreflexia","correct":true},{"id":"s3","text":"T 103.1°F (39.5°C)","correct":false},{"id":"s4","text":"HR 132/min with BP 168/98 mm Hg","correct":true},{"id":"s5","text":"Diarrhea and dilated pupils","correct":true},{"id":"s6","text":"Linezolid started 24 hours ago while taking sertraline","correct":true},{"id":"s7","text":"SpO2 95% on 2 L/min","correct":false},{"id":"s8","text":"WBC 13,800/mm³","correct":false}]}','RNMaster-Set40-Case','1'),
('Set40-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each feature, indicate whether it is more typical of serotonin syndrome or neuroleptic malignant syndrome (NMS). Serotonin','','','Serotonin syndrome: rapid onset, clonus and hyperreflexia, GI hyperactivity and mydriasis, tremor. NMS: lead-pipe rigidity with slowed reflexes, gradual onset after antipsychotic. Both cause hyperthermia and autonomic instability, but neuromuscular findings, timing, and the causative drug help distinguish them. Treatments differ (for example, cyproheptadine for serotonin syndrome and dantrolene or bromocriptine for NMS).','Integrated','Adult Health','{"columns":[{"id":"c1","label":"NMS"}],"rows":[{"id":"r1","label":"Onset within about 24 hours of a medication change","correct":"c1"},{"id":"r2","label":"Clonus and hyperreflexia","correct":"c1"},{"id":"r3","label":"Diarrhea and dilated pupils","correct":"c1"},{"id":"r4","label":"Severe \"lead-pipe\" rigidity with slowed reflexes","correct":"c1"},{"id":"r5","label":"Gradual onset over days after starting an antipsychotic","correct":"c1"},{"id":"r6","label":"Tremor and agitation with hyperactive bowel sounds","correct":"c1"}]}','RNMaster-Set40-Case','2'),
('Set40-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___ and is at risk for ___2___.','','','Muscle-generated heat can rise rapidly and become life-threatening.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["serotonin syndrome from interacting serotonergic drugs","sepsis from pneumonia only","alcohol withdrawal","thyroid storm"],"correct":"serotonin syndrome from interacting serotonergic drugs"},{"id":"b2","options":["severe hyperthermia leading to rhabdomyolysis, seizures, and organ failure","hypoglycemia","hypothermia","constipation"],"correct":"severe hyperthermia leading to rhabdomyolysis, seizures, and organ failure"}]}','RNMaster-Set40-Case','3'),
('Set40-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Stop all serotonergic medications (and review the choice of antibiotic) ☐|Benzodiazepines for agitation and muscle activity ☐|Cyproheptadine (a serotonin antagonist) ☐|Active external cooling and IV fluids ☐|Continuous cardiac monitoring ☐|Physical restraints to control agitation ☐|Acetaminophen as the main treatment for the fever','A,B,C,D,E','Treatment centers on stopping the offending drugs, sedating with benzodiazepines, using cyproheptadine, cooling, and supportive care. Restraints increase muscle activity, heat production, and lactic acidosis. Antipyretics don''t work because the heat comes from muscle activity, not a change in the brain''s temperature set point.','Integrated','Pharmacology','{}','RNMaster-Set40-Case','4'),
('Set40-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The client''s next scheduled tramadol and sertraline doses are due. What should the nurse do?','Give both doses as scheduled|Hold all serotonergic medications and notify the provider immediately|Give sertraline only|Give tramadol with extra ondansetron','B','Continuing serotonergic drugs worsens toxicity. The provider will stop them and may change the antibiotic. The nurse also reviews other contributors such as ondansetron and trazodone.','Integrated','Pharmacology','{}','RNMaster-Set40-Case','5'),
('Set40-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twenty-four hours after treatment begins, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: temperature, vital signs, clonus resolved, mental status. Follow-up: rhabdomyolysis; seizure. Most serotonin syndrome resolves within 24–72 hours after stopping the offending drugs. Rhabdomyolysis requires aggressive fluids to protect the kidneys, and seizures require benzodiazepines and emergency evaluation.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"T 99.5°F (37.5°C)","correct":"c1"},{"id":"r2","label":"HR 92/min, BP 132/80 mm Hg","correct":"c1"},{"id":"r3","label":"Clonus resolved","correct":"c1"},{"id":"r4","label":"Calm and oriented","correct":"c1"},{"id":"r5","label":"CK 18,000 units/L with dark, tea-colored urine","correct":"c1"},{"id":"r6","label":"New generalized seizure","correct":"c1"}]}','RNMaster-Set40-Case','6')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline,response_config,caseid,case_sequence) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method,case_set_id,case_study_id,case_sequence) values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Evaluate each response against the source key and clinical task.','Interpret the case cues and respond in the native NCLEX item format.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,r.response_config::jsonb,case when r.item_type='multiple_response' then 'plus_minus' when r.item_type='single_best_answer' then 'zero_one' else r.item_type end,nullif(r.caseid,''),nullif(r.caseid,''),case when r.case_sequence::int>0 then r.case_sequence::int else null end) on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,response_config=excluded.response_config,source_id=excluded.source_id,case_set_id=excluded.case_set_id,case_study_id=excluded.case_study_id,case_sequence=excluded.case_sequence,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid;
 if r.item_type in ('single_best_answer','multiple_response') then keyarr:=string_to_array(r.keys,','); n:=0; for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop; select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid; if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source answer mapped to native response model; clinical review pending.' where id=qvid;
end loop; end $$; commit;